def transform(grid):
    h,w=len(grid),len(grid[0])
    colors={v for row in grid for v in row if v}
    cells={c:[(i,j) for i in range(h) for j in range(w) if grid[i][j]==c] for c in colors}
    anchor=min(i for i,_ in cells[max(colors)])
    out=[[0]*w for _ in range(h)]
    for c,cs in cells.items():
        top=min(i for i,_ in cs)
        for i,j in cs: out[i-top+anchor][j]=c
    return out
